package com.lmswahbaby;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LmsWahBabyConfig.GROUP)
public interface LmsWahBabyConfig extends Config
{
	String GROUP = "lmswahbaby";

	@ConfigItem(
		keyName = "lmsGames",
		name = "In LMS games",
		description = "Replace chat while you're in a Last Man Standing game",
		position = 1
	)
	default boolean lmsGames()
	{
		return true;
	}

	@ConfigItem(
		keyName = "feroxEnclave",
		name = "In Ferox Enclave",
		description = "Replace chat while you're in Ferox Enclave, including the LMS lobby",
		position = 2
	)
	default boolean feroxEnclave()
	{
		return true;
	}

	@ConfigItem(
		keyName = "casualWorlds",
		name = "Casual LMS worlds too",
		description = "Also work on the free-to-play LMS Casual worlds, not just the Competitive ones",
		position = 3
	)
	default boolean casualWorlds()
	{
		return false;
	}

	@ConfigItem(
		keyName = "replaceOverhead",
		name = "Replace overhead text",
		description = "Also replace the text shown above players' heads",
		position = 4
	)
	default boolean replaceOverhead()
	{
		return true;
	}

	@ConfigItem(
		keyName = "allowedPhrases",
		name = "Allowed phrases",
		description = "Comma-separated messages to leave alone. Case, punctuation, spaces and repeated letters are ignored, "
			+ "longer phrases allow a one-letter typo, and words like \"hf\" or \"all\" may be added around them",
		position = 5
	)
	default String allowedPhrases()
	{
		return "gl, gf, gg, ggs, good luck, good fight, good fite, good game";
	}

	@ConfigItem(
		keyName = "replacements",
		name = "Replacements",
		description = "Comma-separated messages to show instead; one is picked at random each time",
		position = 6
	)
	default String replacements()
	{
		return "Wah, Wahhh!, Waaaaaah, Wah wah wah, *cries*, *sobs*, *sniffles*, *throws controller*, *cries in LMS*";
	}
}

package com.lmswahbaby;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.IterableHashTable;
import net.runelite.api.MessageNode;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.OverheadTextChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(
	name = "LMS WahBaby",
	description = "Turns other players' public chat in Last Man Standing and Ferox Enclave into \"Wah\", except friendly ones like \"gl\", \"gf\" and \"gg\"",
	tags = {"lms", "last man standing", "chat", "ferox", "fun"}
)
public class LmsWahBabyPlugin extends Plugin
{
	/** Map regions of the LMS islands (Deserted Island, then Wild Varrock), as used by RuneLite's loot tracker. */
	private static final Set<Integer> LMS_REGIONS = ImmutableSet.of(
		13658, 13659, 13660, 13914, 13915, 13916,
		13918, 13919, 13920, 14174, 14175, 14176, 14430, 14431, 14432);

	/** Ferox Enclave's walkable area, as rectangles of {minX, minY, maxX, maxY}. */
	private static final int[][] FEROX_ENCLAVE = {
		{3123, 3622, 3124, 3631},
		{3125, 3617, 3140, 3639},
		{3138, 3636, 3155, 3645},
		{3141, 3625, 3154, 3635},
	};

	/** How long a replacement is remembered so the chat line and overhead text match. */
	private static final int REMEMBER_TICKS = 5;

	/** Replaced chat lines remembered for restoring; more than the chatbox keeps, so none are missed. */
	private static final int MAX_TRACKED_MESSAGES = 1000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private LmsWahBabyConfig config;

	private PhraseMatcher matcher;
	private List<String> replacements;

	/** Recent replacements by player name, so a message's chat line and overhead text show the same thing. */
	private final Map<String, Replacement> recent = new HashMap<>();

	/** Chat lines this plugin replaced, by message id, so turning the plugin off can put them back. */
	private final Map<Integer, Replacement> replacedMessages = new LinkedHashMap<Integer, Replacement>()
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Integer, Replacement> eldest)
		{
			return size() > MAX_TRACKED_MESSAGES;
		}
	};

	@Override
	protected void startUp()
	{
		loadConfig();
	}

	@Override
	protected void shutDown()
	{
		Map<Integer, Replacement> messages = new HashMap<>(replacedMessages);
		Map<String, Replacement> overheads = new HashMap<>(recent);
		replacedMessages.clear();
		recent.clear();
		clientThread.invoke(() -> restoreOriginals(messages, overheads));
	}

	/** Puts back the original text of chat lines and overhead text this plugin replaced. */
	private void restoreOriginals(Map<Integer, Replacement> messages, Map<String, Replacement> overheads)
	{
		IterableHashTable<MessageNode> chatHistory = client.getMessages();
		if (chatHistory != null)
		{
			for (Map.Entry<Integer, Replacement> entry : messages.entrySet())
			{
				MessageNode node = chatHistory.get(entry.getKey());
				// Skip lines that have left the chat history or were changed again by something else.
				if (node != null && entry.getValue().text.equals(node.getValue()))
				{
					node.setValue(entry.getValue().original);
				}
			}
			client.refreshChat();
		}

		WorldView worldView = client.getTopLevelWorldView();
		if (worldView == null)
		{
			return;
		}

		for (Player player : worldView.players())
		{
			if (player == null || player.getName() == null)
			{
				continue;
			}

			Replacement replacement = overheads.get(Text.standardize(player.getName()));
			if (replacement != null && replacement.text.equals(player.getOverheadText()))
			{
				player.setOverheadText(replacement.original);
			}
		}
	}

	@Provides
	LmsWahBabyConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(LmsWahBabyConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (LmsWahBabyConfig.GROUP.equals(event.getGroup()))
		{
			loadConfig();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		int now = client.getTickCount();
		recent.values().removeIf(r -> now - r.tick > REMEMBER_TICKS);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if ((event.getType() != ChatMessageType.PUBLICCHAT && event.getType() != ChatMessageType.AUTOTYPER)
			|| event.getName() == null)
		{
			return;
		}

		String name = Text.standardize(event.getName());
		String original = event.getMessage();
		if (name.isEmpty() || isLocalPlayer(name) || !isActive() || matcher.isAllowed(original))
		{
			return;
		}

		String replacement = replacementFor(name, original);
		MessageNode node = event.getMessageNode();
		replacedMessages.put(node.getId(), new Replacement(node.getValue(), replacement, client.getTickCount()));
		node.setValue(replacement);

		// The overhead text may already be showing the original message.
		if (config.replaceOverhead())
		{
			for (Player player : client.getTopLevelWorldView().players())
			{
				// Players whose name hasn't loaded yet have a null name.
				if (player != null && player.getName() != null && name.equals(Text.standardize(player.getName()))
					&& sameText(player.getOverheadText(), original))
				{
					player.setOverheadText(replacement);
				}
			}
		}
	}

	@Subscribe
	public void onOverheadTextChanged(OverheadTextChanged event)
	{
		if (!config.replaceOverhead() || !(event.getActor() instanceof Player) || event.getActor().getName() == null)
		{
			return;
		}

		// Only replace overhead text that came from a chat message we replaced, so special
		// attack shouts and other game-set text are left alone. If the overhead text arrives
		// before the chat message, onChatMessage replaces it instead.
		Replacement replacement = recent.get(Text.standardize(event.getActor().getName()));
		if (replacement != null && sameText(event.getOverheadText(), replacement.original))
		{
			event.getActor().setOverheadText(replacement.text);
		}
	}

	private String replacementFor(String name, String original)
	{
		Replacement previous = recent.get(name);
		if (previous != null && sameText(previous.original, original))
		{
			return previous.text;
		}

		String text = replacements.get(ThreadLocalRandom.current().nextInt(replacements.size()));
		recent.put(name, new Replacement(original, text, client.getTickCount()));
		return text;
	}

	private boolean isActive()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}

		EnumSet<WorldType> worldTypes = client.getWorldType();
		boolean lmsWorld = worldTypes.contains(WorldType.LAST_MAN_STANDING);
		boolean competitive = worldTypes.contains(WorldType.MEMBERS);
		if (!lmsWorld || (!competitive && !config.casualWorlds()))
		{
			return false;
		}

		return (config.lmsGames() && isInLmsGame()) || (config.feroxEnclave() && isInFeroxEnclave());
	}

	private boolean isInLmsGame()
	{
		for (int region : client.getTopLevelWorldView().getMapRegions())
		{
			if (LMS_REGIONS.contains(region))
			{
				return true;
			}
		}
		return false;
	}

	private boolean isInFeroxEnclave()
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}

		WorldPoint location = local.getWorldLocation();
		for (int[] area : FEROX_ENCLAVE)
		{
			if (location.getX() >= area[0] && location.getY() >= area[1]
				&& location.getX() <= area[2] && location.getY() <= area[3])
			{
				return true;
			}
		}
		return false;
	}

	private boolean isLocalPlayer(String standardizedName)
	{
		Player local = client.getLocalPlayer();
		return local != null && local.getName() != null && standardizedName.equals(Text.standardize(local.getName()));
	}

	private static boolean sameText(String a, String b)
	{
		return a != null && b != null && Text.standardize(a).equals(Text.standardize(b));
	}

	private void loadConfig()
	{
		matcher = new PhraseMatcher(Text.fromCSV(config.allowedPhrases()));

		List<String> parsed = new ArrayList<>();
		for (String text : Text.fromCSV(config.replacements()))
		{
			if (!text.isEmpty())
			{
				parsed.add(text);
			}
		}
		if (parsed.isEmpty())
		{
			parsed.add("Wah");
		}
		replacements = parsed;
	}

	private static final class Replacement
	{
		private final String original;
		private final String text;
		private final int tick;

		private Replacement(String original, String text, int tick)
		{
			this.original = original;
			this.text = text;
			this.tick = tick;
		}
	}
}

package com.lmswahbaby;

import java.util.Collection;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/**
 * Decides whether a chat message is only a friendly "gl" / "gf" style message.
 * <p>
 * Messages are compared loosely: case, spaces, punctuation, chat tags and repeated
 * letters are ignored ("GL!!", "g l", "gooood luck" all match), longer phrases also
 * accept a one-letter typo ("gud luck", "goodluk"), phrases may be repeated or combined
 * ("glglgl", "gg gl", "GGGGG"), and a few harmless extra words are allowed around them
 * ("gl hf", "gf all", "gl everyone"). Anything else, including "gl" followed by an insult,
 * is not allowed.
 */
final class PhraseMatcher
{
	/**
	 * Words that may sit next to an allowed phrase without changing its meaning.
	 * On their own they don't count as allowed.
	 */
	private static final String[] FILLER_WORDS = {
		"all", "everyone", "every1", "guys", "lads", "boys", "gents", "yall",
		"hf", "have fun", "ty", "thx", "thanks", "and", "n", "mate", "m8", "man", "bro",
	};

	/** Phrases this short must match exactly; a one-letter typo would match too much. */
	private static final int MIN_LENGTH_FOR_TYPOS = 6;

	private final Set<String> allowed = new HashSet<>();
	private final Set<String> fillers = new HashSet<>();

	PhraseMatcher(Collection<String> allowedPhrases)
	{
		for (String phrase : allowedPhrases)
		{
			String normalized = normalize(phrase);
			if (!normalized.isEmpty())
			{
				allowed.add(normalized);
			}
		}

		for (String filler : FILLER_WORDS)
		{
			fillers.add(normalize(filler));
		}
	}

	boolean isAllowed(String message)
	{
		if (message == null)
		{
			return false;
		}

		String text = normalize(message);
		int length = text.length();
		if (length == 0)
		{
			return false;
		}

		// Split the text into allowed phrases and filler words, needing at least one
		// allowed phrase. withPhrase[i]: text[0, i) splits with at least one allowed phrase;
		// onlyFillers[i]: text[0, i) splits into filler words only.
		boolean[] withPhrase = new boolean[length + 1];
		boolean[] onlyFillers = new boolean[length + 1];
		onlyFillers[0] = true;

		for (int start = 0; start < length; start++)
		{
			if (!withPhrase[start] && !onlyFillers[start])
			{
				continue;
			}

			for (int end = start + 1; end <= length; end++)
			{
				String part = text.substring(start, end);

				if (matchesAllowed(part))
				{
					withPhrase[end] = true;
				}

				if (fillers.contains(part))
				{
					withPhrase[end] |= withPhrase[start];
					onlyFillers[end] |= onlyFillers[start];
				}
			}
		}

		return withPhrase[length];
	}

	private boolean matchesAllowed(String part)
	{
		if (allowed.contains(part))
		{
			return true;
		}

		for (String phrase : allowed)
		{
			if (phrase.length() >= MIN_LENGTH_FOR_TYPOS
				&& Math.abs(phrase.length() - part.length()) <= 1
				&& typoDistance(phrase, part) <= 1)
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Lowercases, strips chat tags, keeps only letters and digits, and squashes repeated
	 * characters ("Gooood   Luck!!" becomes "godluck").
	 */
	static String normalize(String text)
	{
		String lettersOnly = text
			.replaceAll("<[^>]*>", "")
			.toLowerCase(Locale.ROOT)
			.replaceAll("[^a-z0-9]", "");
		return lettersOnly.replaceAll("(.)\\1+", "$1");
	}

	/**
	 * Edit distance where swapping two neighbouring letters counts as one typo
	 * (optimal string alignment distance).
	 */
	static int typoDistance(String a, String b)
	{
		int[][] d = new int[a.length() + 1][b.length() + 1];
		for (int i = 0; i <= a.length(); i++)
		{
			d[i][0] = i;
		}
		for (int j = 0; j <= b.length(); j++)
		{
			d[0][j] = j;
		}

		for (int i = 1; i <= a.length(); i++)
		{
			for (int j = 1; j <= b.length(); j++)
			{
				int cost = a.charAt(i - 1) == b.charAt(j - 1) ? 0 : 1;
				d[i][j] = Math.min(Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1), d[i - 1][j - 1] + cost);

				if (i > 1 && j > 1 && a.charAt(i - 1) == b.charAt(j - 2) && a.charAt(i - 2) == b.charAt(j - 1))
				{
					d[i][j] = Math.min(d[i][j], d[i - 2][j - 2] + 1);
				}
			}
		}

		return d[a.length()][b.length()];
	}
}

package com.lmswahbaby;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Starts a development copy of RuneLite with this plugin loaded (run with ./gradlew run). */
public class LmsWahBabyPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LmsWahBabyPlugin.class);
		RuneLite.main(args);
	}
}

package com.lmswahbaby;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import org.junit.Test;

public class PhraseMatcherTest
{
	private final PhraseMatcher matcher = new PhraseMatcher(
		Arrays.asList("gl", "gf", "gg", "ggs", "good luck", "good fight", "good fite", "good game"));

	@Test
	public void allowsGoodLuckAndGoodFight()
	{
		for (String message : new String[]{
			"gl", "GL", "gl!", "GL!!!", "g l", "gll", "glgl",
			"good luck", "Good Luck :)", "goodluck", "gooood luck", "gud luck", "goodluk", "good lcuk",
			"gf", "GF", "gf.", "gff", "g f",
			"good fight", "Good fight!", "gud fight", "good fite", "gd fight",
			"gl hf", "glhf", "GL HF!", "gl and hf", "gl n hf", "good luck have fun",
			"gf gl", "gfgl", "gl gf",
			"gl all", "gf everyone", "gl guys", "gf bro", "ty gf", "gf ty",
			"<col=ff0000>gl</col>", "gl hf",
			"gg", "GG", "GGGGG", "gg!", "g g", "ggs", "gg all", "gg everyone", "ty gg",
			"good game", "Good game!", "goodgame", "gud game", "good gaem",
			"glglgl", "GLGLGL", "gl gl gl", "gfgfgf", "gf gf", "gggg gl", "gl gg", "gg gf gl",
			"good luck good luck", "good game gg", "gg good fight",
		})
		{
			assertTrue("should allow: " + message, matcher.isAllowed(message));
		}
	}

	@Test
	public void replacesEverythingElse()
	{
		for (String message : new String[]{
			"", "   ", ":)", "?", "ez", "sit", "hf", "all", "ty", "lol",
			"gl noob", "gf kid", "trash gf", "gfy", "gl ur bad", "ez gf",
			"good luck you'll need it", "gl next time",
			"gg ez", "ez gg", "gg noob", "gg kid", "gg go next", "gg no re", "ggez", "gg sit",
		})
		{
			assertFalse("should replace: " + message, matcher.isAllowed(message));
		}
	}

	@Test
	public void handlesNull()
	{
		assertFalse(matcher.isAllowed(null));
	}

	@Test
	public void emptyAllowListAllowsNothing()
	{
		PhraseMatcher empty = new PhraseMatcher(Arrays.asList("", " "));
		assertFalse(empty.isAllowed("gl"));
		assertFalse(empty.isAllowed("gl hf"));
	}
}
